<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {getAuthContextVersion} from '@/api/http'
import {useAuthStore} from '@/stores/auth'
import {useLegacyActivityStore} from '@/stores/legacyActivity'
import {useLegacyActivityStatus} from '@/composables/useLegacyActivityStatus'
import {fpConfirm} from '@/composables/useDialog'
const auth=useAuthStore(),writes=useLegacyActivityStore(),{checkin,reward}=useLegacyActivityStatus(),mounted=ref(false),confirming=ref(false),loggedIn=computed(()=>mounted.value&&!!auth.apiKey&&!!auth.account?.oId);let confirmation:AbortController|null=null
const identity=()=>JSON.stringify([getAuthContextVersion(),auth.apiKey,auth.account?.oId]);function cancel(){confirmation?.abort();confirmation=null;confirming.value=false}
async function collect(){if(!loggedIn.value||writes.pending||writes.busy||confirming.value||reward.value.value?.claimed!==false)return;const original=reward.value.value,reader=identity(),controller=new AbortController();confirmation=controller;confirming.value=true
 try{const yes=await fpConfirm({title:'尝试领取昨日活跃奖励',message:'旧接口无法预览奖励日期和金额，未领取也不代表满足领取条件。确认后将尝试领取服务器当时的昨日奖励，是否继续？',confirmText:'确认尝试领取',signal:controller.signal});if(yes&&!controller.signal.aborted&&reader===identity()&&reward.value.value===original&&!writes.pending&&!writes.busy)await writes.claim()}
 finally{if(confirmation===controller){confirmation=null;confirming.value=false}}}
watch(identity,cancel,{flush:'sync'});onMounted(()=>{mounted.value=true});onBeforeUnmount(()=>{mounted.value=false;cancel()})
</script>
<template><div v-if="loggedIn" class="checkin-card"><section aria-label="今日签到"><h3>今日签到</h3><p v-if="checkin.loading.value" role="status">正在读取签到状态…</p><p v-else-if="checkin.error.value" role="alert">{{ checkin.error.value }} <button type="button" @click="checkin.read()">重试签到状态</button></p><template v-else-if="checkin.value.value"><p>活跃度 {{ checkin.value.value.liveness }}% · 自动签到门槛 {{ checkin.value.value.threshold }}%</p><div class="progress-track"><div :style="{width:Math.min(100,checkin.value.value.liveness)+'%'}"/></div><p>{{ checkin.value.value.checkedIn?'今日已签到':'今日尚未签到，活跃达标后自动签到' }} · 连续 {{ checkin.value.value.streak }} 天</p><button type="button" @click="checkin.read()">刷新签到状态</button></template></section><section aria-label="昨日活跃奖励"><h3>昨日活跃奖励</h3><p v-if="reward.loading.value" role="status">正在读取奖励状态…</p><p v-else-if="reward.error.value" role="alert">{{ reward.error.value }} <button type="button" @click="reward.read()">重试奖励状态</button></p><template v-else-if="reward.value.value"><p>{{ reward.value.value.claimed?'昨日奖励已领取':'昨日奖励尚未领取' }}。旧接口未提供可预览的日期、金额及领取资格。</p><button type="button" @click="reward.read()">刷新奖励状态</button><button v-if="!reward.value.value.claimed" type="button" :disabled="writes.busy||writes.pending||confirming" @click="collect">尝试领取昨日奖励</button></template></section></div></template>
<style scoped lang="scss">.checkin-card{display:grid;gap:16px;section{min-width:0}h3{margin:0 0 8px;font-size:15px}p{font-size:13px;line-height:1.6}button{font:inherit;margin:3px;padding:6px 9px;border:1px solid var(--fp-border);border-radius:5px;background:var(--fp-card);color:var(--fp-text)}[role=alert]{color:#bd503c}}.progress-track{height:6px;background:var(--fp-border);overflow:hidden;border-radius:3px;div{height:100%;background:#6cad5a}}</style>
